#include "so101_gazebo_demo/pick_place/runner.hpp"
namespace so101_gazebo_demo::pick_place {
namespace { StateActionRegistry kEmptyActions; TransitionContractRegistry kEmptyContracts; }
StateMachineRunner::StateMachineRunner():StateMachineRunner(kEmptyActions,kEmptyContracts){}
StateMachineRunner::StateMachineRunner(const StateActionRegistry&a,const TransitionContractRegistry&c,IWorldObserver*o,ICheckpointStore*s,const CommonResumeValidator*r,const PlanValidatorRegistry*v,const IRecoveryPolicy*p):actions_(a),contracts_(c),observer_(o),store_(s),resume_(r),validators_(v),recovery_(p){}
RunResult StateMachineRunner::error(Failure f)const{return {RunStatus::ERROR,State::ERROR,{},std::move(f),0,{}};}
RunResult StateMachineRunner::dry(const RunRequest&q)const{StateMachine m;RunResult r; r.status=RunStatus::RUNNING;r.state_trace.push_back(State::IDLE);while(!m.isTerminal()&&r.transition_count<q.max_state_transitions){auto s=m.currentState();auto n=m.advance(q.fail_at==s?ActionStatus::FAILED:ActionStatus::SUCCEEDED);++r.transition_count;r.state_trace.push_back(n);if(q.fail_at==s)r.failure=Failure{FailureCategory::INTERNAL,"DRY_RUN_FAILURE_INJECTED","injected",{}};if(q.stop_after==s&&q.fail_at!=s){r.status=RunStatus::CHECKPOINT_COMPLETE;r.current_state=n;r.next_state=n;return r;}}r.current_state=m.currentState();r.status=r.current_state==State::DONE?RunStatus::DONE:RunStatus::ERROR;return r;}
RunResult StateMachineRunner::execute(State state,const RunRequest&q,std::optional<WorldSnapshot> before,std::uint64_t seq)const{RunResult r; r.status=RunStatus::RUNNING;while(!isTerminal(state)&&r.transition_count<q.max_state_transitions){r.state_trace.push_back(state);auto next=TransitionTable::resolve(state,ActionStatus::SUCCEEDED);auto* ex=actions_.findExecutor(state);if(!observer_||!store_||!resume_||!ex)return error({FailureCategory::CONFIGURATION,"EXECUTE_INFRASTRUCTURE_MISSING","missing observer/store/validator/executor",{}});if(!contracts_.hasContract({state,next}))return error({FailureCategory::CONFIGURATION,"MISSING_TRANSITION_CONTRACT","contract missing",{}});auto obs=before?ObservationResult{before,{}}:observer_->observe();before.reset();if(!obs.snapshot)return error({FailureCategory::OBSERVATION,"PRE_EXECUTION_OBSERVATION_FAILED","observation missing",{}});std::shared_ptr<const PlanArtifact> plan;if(auto*p=actions_.findPlanner(state)){if(!validators_||!validators_->hasValidator(state))return error({FailureCategory::CONFIGURATION,"PLAN_VALIDATOR_NOT_REGISTERED","validator missing",{}});auto pr=p->plan(state,next,obs);if(pr.action.status!=ActionStatus::SUCCEEDED||!pr.artifact)return error({FailureCategory::PLANNING,"PLAN_FAILED","plan failed",{}});if(!validators_->validate(state,*obs.snapshot,*pr.artifact).ok)return error({FailureCategory::PLAN_VALIDATION,"PLAN_INVALID","plan invalid",{}});plan=pr.artifact;}auto action=ex->execute({state,next,*obs.snapshot,plan});if(action.status!=ActionStatus::SUCCEEDED){ex->cancel();auto stopped=observer_->observe();if(!stopped.snapshot||!recovery_)return error(action.failure.value_or(Failure{FailureCategory::EXECUTION,"EXECUTION_FAILED","execution failed",{}}));auto route=recovery_->select(state,*action.failure,*stopped.snapshot);if(!route.next_state)return error(route.failure.value_or(Failure{FailureCategory::INTERNAL,"RECOVERY_ROUTE_MISSING","route missing",{}}));Checkpoint cp;cp.phase=CheckpointPhase::RECOVERY;cp.last_completed_state=state;cp.failed_state=state;cp.original_failure=action.failure;cp.next_state=*route.next_state;cp.configuration_hash=resume_->configurationHash();cp.simulation_session_id=resume_->simulationSessionId();store_->commit(cp);state=*route.next_state;continue;}auto after=observer_->observe();if(!after.snapshot||!contracts_.validate({state,next},*obs.snapshot,*after.snapshot,action).ok)return error({FailureCategory::POSTCONDITION,"POSTCONDITION_FAILED","postcondition failed",{}});Checkpoint cp;cp.sequence=seq++;cp.last_completed_state=state;cp.next_state=next;cp.configuration_hash=resume_->configurationHash();cp.simulation_session_id=resume_->simulationSessionId();cp.expected.joint_positions=after.snapshot->joint_positions;store_->commit(cp);++r.transition_count;if(q.stop_after==state){r.status=RunStatus::CHECKPOINT_COMPLETE;r.current_state=next;r.next_state=next;return r;}state=next;}r.current_state=state;r.status=state==State::DONE?RunStatus::DONE:RunStatus::ERROR;return r;}
RunResult StateMachineRunner::run(const RunRequest&q)const{if(q.mode==RunMode::DRY_RUN)return dry(q);if(q.resume){if(!store_||!observer_||!resume_)return error({FailureCategory::RESUME_VALIDATION,"RESUME_INFRASTRUCTURE_MISSING","resume infra missing",{}});auto l=store_->loadLatestCompatible();if(!l.checkpoint)return error(l.failure.value_or(Failure{FailureCategory::CHECKPOINT,"CHECKPOINT_LOAD_FAILED","load failed",{}}));auto o=observer_->observe();if(!o.snapshot)return error({FailureCategory::OBSERVATION,"RESUME_OBSERVATION_FAILED","observe failed",{}});if(!resume_->validate(*l.checkpoint,*o.snapshot).ok)return error({FailureCategory::RESUME_VALIDATION,"RESUME_BOUNDARY_INVALID","boundary invalid",{}});return execute(l.checkpoint->next_state,q,*o.snapshot,l.checkpoint->sequence+1);}if(q.mode==RunMode::PLAN_ONLY){auto*p=actions_.findPlanner(State::MOVE_ABOVE_OBJECT);if(!p||!observer_||!validators_)return error({FailureCategory::CONFIGURATION,"PLAN_ONLY_INFRASTRUCTURE_MISSING","plan infra missing",{}});auto o=observer_->observe();if(!o.snapshot)return error({FailureCategory::OBSERVATION,"TARGET_OBSERVATION_FAILED","observe failed",{}});auto plan=p->plan(State::MOVE_ABOVE_OBJECT,State::DESCEND,o);if(plan.action.status!=ActionStatus::SUCCEEDED||!plan.artifact||!validators_->validate(State::MOVE_ABOVE_OBJECT,*o.snapshot,*plan.artifact).ok)return error({FailureCategory::PLAN_VALIDATION,"PLAN_INVALID","plan invalid",{}});return {RunStatus::PLAN_ONLY_COMPLETE,State::MOVE_ABOVE_OBJECT,State::DESCEND,{},0,{State::MOVE_ABOVE_OBJECT}};}return execute(State::PREPARE_OPEN_GRIPPER,q,{},1);}
}
